import * as dotenv from 'dotenv'; dotenv.config({ path: '.env.local' });
import { neon } from '@neondatabase/serverless';
const sql = neon(process.env.DATABASE_URL!);
async function main() {
  const rows = await sql.query(\`
    SELECT
      COUNT(*) FILTER (WHERE UPPER(TRIM(r.vlm_ont_serial_step6)) = UPPER(TRIM(r.oes_serial))) as s6_match,
      COUNT(*) FILTER (WHERE r.vlm_ont_serial_step6 IS NOT NULL AND r.vlm_ont_serial_step6 <> '') as s6_total,
      COUNT(*) FILTER (WHERE UPPER(TRIM(r.vlm_ont_serial_step9)) = UPPER(TRIM(r.oes_serial))) as s9_match,
      COUNT(*) FILTER (WHERE r.vlm_ont_serial_step9 IS NOT NULL AND r.vlm_ont_serial_step9 <> '') as s9_total
    FROM dr_photo_unified_reviews r
    JOIN oes_activations o ON o.drop_number = r.drop_number
    WHERE o.created_at >= (NOW() - INTERVAL '14 days')
      AND r.oes_serial IS NOT NULL AND r.oes_serial <> ''
  \`);
  const r = rows[0];
  const s6pct = r.s6_total > 0 ? ((r.s6_match/r.s6_total)*100).toFixed(1) : 'N/A';
  const s9pct = r.s9_total > 0 ? ((r.s9_match/r.s9_total)*100).toFixed(1) : 'N/A';
  console.log('=== ONT Serial Accuracy (last 14 days) ===');
  console.log('Step 6: ' + r.s6_match + '/' + r.s6_total + ' = ' + s6pct + '%');
  console.log('Step 9: ' + r.s9_match + '/' + r.s9_total + ' = ' + s9pct + '%');

  // WA serial accuracy
  const wa = await sql.query(\`
    WITH wa_best AS (
      SELECT DISTINCT ON (drop_number) drop_number, vlm_ont_serial
      FROM wa_photos WHERE purpose = 'activation' AND vlm_processed = true AND vlm_ont_serial IS NOT NULL
        AND message_timestamp >= (NOW() - INTERVAL '14 days')
      ORDER BY drop_number, vlm_confidence DESC NULLS LAST
    )
    SELECT COUNT(*) as total,
      COUNT(*) FILTER (WHERE UPPER(TRIM(w.vlm_ont_serial)) = UPPER(TRIM(o.serial_number))) as matched
    FROM wa_best w JOIN oes_activations o ON o.drop_number = w.drop_number
    WHERE o.created_at >= (NOW() - INTERVAL '14 days')
  \`);
  const wapct = wa[0].total > 0 ? ((wa[0].matched/wa[0].total)*100).toFixed(1) : 'N/A';
  console.log('WA:     ' + wa[0].matched + '/' + wa[0].total + ' = ' + wapct + '%');

  // Overall vlm_corrections stats
  const corrections = await sql.query(\`
    SELECT module, analysis_type, COUNT(*) as count
    FROM vlm_corrections
    WHERE created_at >= NOW() - INTERVAL '14 days'
    GROUP BY 1, 2 ORDER BY 3 DESC
  \`);
  console.log('\\n=== Recent Corrections (14 days) ===');
  for (const c of corrections) {
    console.log(c.module + '/' + c.analysis_type + ': ' + c.count);
  }

  // vlm_metrics recent
  const metrics = await sql.query(\`
    SELECT date, module, analysis_type, total_extractions, correct_extractions,
           ROUND(correct_extractions::numeric / NULLIF(total_extractions, 0) * 100, 1) as accuracy
    FROM vlm_metrics
    WHERE date >= CURRENT_DATE - 7
    ORDER BY date DESC, module
  \`);
  console.log('\\n=== VLM Metrics (last 7 days) ===');
  for (const m of metrics) {
    console.log(m.date + ' | ' + m.module + '/' + m.analysis_type + ': ' + m.correct_extractions + '/' + m.total_extractions + ' = ' + m.accuracy + '%');
  }
}
main().catch(console.error);
"
