import * as dotenv from 'dotenv'; dotenv.config({ path: '.env.local' });
import { neon } from '@neondatabase/serverless';
const sql = neon(process.env.DATABASE_URL!);
async function main() {
  // Photo categorization accuracy
  const cat = await sql.query(\`
    WITH exploded AS (
      SELECT
        r.id,
        (elem->>'vlm_predicted_step')::int as vlm_step,
        (elem->>'human_override_step')::int as human_step,
        elem->>'photo_url' as photo_url
      FROM dr_photo_unified_reviews r,
           jsonb_array_elements(r.vlm_categorization_results) elem
      WHERE r.vlm_categorization_results IS NOT NULL
        AND r.created_at >= NOW() - INTERVAL '14 days'
        AND elem->>'human_override_step' IS NOT NULL
    )
    SELECT
      COUNT(*) as total_reviewed,
      COUNT(*) FILTER (WHERE vlm_step = human_step) as correct,
      ROUND(COUNT(*) FILTER (WHERE vlm_step = human_step)::numeric / NULLIF(COUNT(*), 0) * 100, 1) as accuracy
    FROM exploded
  \`);
  console.log('=== Photo Categorization Accuracy (14 days) ===');
  console.log('Correct: ' + cat[0].correct + '/' + cat[0].total_reviewed + ' = ' + cat[0].accuracy + '%');

  // Confusion matrix for categorization
  const confusion = await sql.query(\`
    WITH exploded AS (
      SELECT
        (elem->>'vlm_predicted_step')::int as vlm_step,
        (elem->>'human_override_step')::int as human_step
      FROM dr_photo_unified_reviews r,
           jsonb_array_elements(r.vlm_categorization_results) elem
      WHERE r.vlm_categorization_results IS NOT NULL
        AND r.created_at >= NOW() - INTERVAL '30 days'
        AND elem->>'human_override_step' IS NOT NULL
        AND (elem->>'vlm_predicted_step')::int != (elem->>'human_override_step')::int
    )
    SELECT vlm_step, human_step, COUNT(*) as count
    FROM exploded
    GROUP BY 1, 2
    ORDER BY 3 DESC
    LIMIT 15
  \`);
  console.log('\\n=== Categorization Confusion (top 15, 30 days) ===');
  console.log('VLM_Step -> Human_Step : Count');
  for (const c of confusion) {
    console.log('  Step ' + c.vlm_step + ' -> Step ' + c.human_step + ' : ' + c.count);
  }

  // Power meter accuracy (if data exists)
  const power = await sql.query(\`
    SELECT
      COUNT(*) as total,
      COUNT(*) FILTER (WHERE vlm_power_dbm IS NOT NULL) as extracted,
      AVG(ABS(vlm_power_dbm - oes_power_dbm)) FILTER (WHERE vlm_power_dbm IS NOT NULL AND oes_power_dbm IS NOT NULL) as avg_diff
    FROM dr_photo_unified_reviews
    WHERE created_at >= NOW() - INTERVAL '14 days'
      AND (vlm_power_dbm IS NOT NULL OR oes_power_dbm IS NOT NULL)
  \`);
  console.log('\\n=== Power Meter (14 days) ===');
  console.log('Extracted: ' + power[0].extracted + '/' + power[0].total);
  if (power[0].avg_diff) console.log('Avg diff from OES: ' + parseFloat(power[0].avg_diff).toFixed(2) + ' dBm');

  // Error patterns from vlm_corrections
  const patterns = await sql.query(\`
    SELECT error_pattern, COUNT(*) as count
    FROM vlm_corrections
    WHERE created_at >= NOW() - INTERVAL '30 days'
      AND error_pattern IS NOT NULL AND error_pattern <> ''
    GROUP BY 1 ORDER BY 2 DESC LIMIT 10
  \`);
  console.log('\\n=== Top Error Patterns (30 days) ===');
  for (const p of patterns) {
    console.log('  ' + p.error_pattern + ': ' + p.count);
  }
}
main().catch(console.error);
"
