const sql = neon(process.env.DATABASE_URL!);
async function main() {
  // Step 6 mismatches detail
  const s6 = await sql.query(\`
    SELECT r.vlm_ont_serial_step6 as vlm, r.oes_serial as oes, r.drop_number
    FROM dr_photo_unified_reviews r
    JOIN oes_activations o ON o.drop_number = r.drop_number
    WHERE o.created_at >= (NOW() - INTERVAL '14 days')
      AND r.oes_serial IS NOT NULL AND r.oes_serial <> ''
      AND r.vlm_ont_serial_step6 IS NOT NULL AND r.vlm_ont_serial_step6 <> ''
      AND UPPER(TRIM(r.vlm_ont_serial_step6)) != UPPER(TRIM(r.oes_serial))
    ORDER BY r.created_at DESC LIMIT 30
  \`);
  console.log('=== Step 6 Mismatches (recent 30) ===');
  console.log('VLM_Serial        | OES_Serial        | DR');
  for (const r of s6) {
    console.log((r.vlm||'').padEnd(18) + '| ' + (r.oes||'').padEnd(18) + '| ' + r.drop_number);
  }

  // Step 9 mismatches detail
  const s9 = await sql.query(\`
    SELECT r.vlm_ont_serial_step9 as vlm, r.oes_serial as oes, r.drop_number
    FROM dr_photo_unified_reviews r
    JOIN oes_activations o ON o.drop_number = r.drop_number
    WHERE o.created_at >= (NOW() - INTERVAL '14 days')
      AND r.oes_serial IS NOT NULL AND r.oes_serial <> ''
      AND r.vlm_ont_serial_step9 IS NOT NULL AND r.vlm_ont_serial_step9 <> ''
      AND UPPER(TRIM(r.vlm_ont_serial_step9)) != UPPER(TRIM(r.oes_serial))
    ORDER BY r.created_at DESC LIMIT 30
  \`);
  console.log('\n=== Step 9 Mismatches (recent 30) ===');
  console.log('VLM_Serial        | OES_Serial        | DR');
  for (const r of s9) {
    console.log((r.vlm||'').padEnd(18) + '| ' + (r.oes||'').padEnd(18) + '| ' + r.drop_number);
  }

  // Character-level confusion
  const charConf = await sql.query(\`
    SELECT r.vlm_ont_serial_step6 as vlm, r.oes_serial as oes
    FROM dr_photo_unified_reviews r
    JOIN oes_activations o ON o.drop_number = r.drop_number
    WHERE r.oes_serial IS NOT NULL AND r.oes_serial <> ''
      AND r.vlm_ont_serial_step6 IS NOT NULL AND r.vlm_ont_serial_step6 <> ''
      AND UPPER(TRIM(r.vlm_ont_serial_step6)) != UPPER(TRIM(r.oes_serial))
      AND LENGTH(TRIM(r.vlm_ont_serial_step6)) = 12 AND LENGTH(TRIM(r.oes_serial)) = 12
    LIMIT 200
  \`);
  const posErrors: Record<number, Record<string, number>> = {};
  for (const r of charConf) {
    const v = r.vlm.trim().toUpperCase();
    const o = r.oes.trim().toUpperCase();
    for (let i = 0; i < 12; i++) {
      if (v[i] !== o[i]) {
        if (!posErrors[i]) posErrors[i] = {};
        const key = v[i] + '->' + o[i];
        posErrors[i][key] = (posErrors[i][key] || 0) + 1;
      }
    }
  }
  console.log('\n=== Character-Level Confusion (pos: vlm->oes count) ===');
  for (const [pos, errs] of Object.entries(posErrors).sort((a,b) => Number(a[0]) - Number(b[0]))) {
    const sorted = Object.entries(errs).sort((a,b) => b[1] - a[1]).slice(0, 5);
    console.log('Pos ' + pos + ': ' + sorted.map(([k,v]) => k + '(' + v + ')').join(', '));
  }

  // Position 7 distribution
  const stats = await sql.query(\`
    SELECT oes_serial FROM dr_photo_unified_reviews
    WHERE oes_serial IS NOT NULL AND oes_serial <> ''
      AND LENGTH(TRIM(oes_serial)) = 12 AND UPPER(LEFT(TRIM(oes_serial), 6)) = 'ALCLB4'
  \`);
  const c7: Record<string, number> = {};
  for (const r of stats) {
    const s = r.oes_serial.trim().toUpperCase();
    c7[s[6]] = (c7[s[6]] || 0) + 1;
  }
  const total = stats.length;
  console.log('\nPosition 7 Distribution (' + total + ' serials):');
  console.log(Object.entries(c7).sort((a,b)=>b[1]-a[1]).map(([c,n])=>c+'='+((n/total)*100).toFixed(1)+'%').join(', '));

  // Step 9: many mismatches might be wrong photo (not ONT). Check how many Step 9 VLM results dont start with ALCLB4
  const s9format = await sql.query(\`
    SELECT
      COUNT(*) as total,
      COUNT(*) FILTER (WHERE UPPER(LEFT(TRIM(vlm_ont_serial_step9), 6)) = 'ALCLB4') as valid_prefix,
      COUNT(*) FILTER (WHERE LENGTH(TRIM(vlm_ont_serial_step9)) != 12) as wrong_length,
      COUNT(*) FILTER (WHERE UPPER(LEFT(TRIM(vlm_ont_serial_step9), 6)) != 'ALCLB4' AND vlm_ont_serial_step9 IS NOT NULL AND vlm_ont_serial_step9 <> '') as bad_prefix
    FROM dr_photo_unified_reviews
    WHERE vlm_ont_serial_step9 IS NOT NULL AND vlm_ont_serial_step9 <> ''
      AND created_at >= NOW() - INTERVAL '14 days'
  \`);
  console.log('\nStep 9 Format Quality (14 days):');
  console.log('Total: ' + s9format[0].total + ', Valid prefix: ' + s9format[0].valid_prefix + ', Bad prefix: ' + s9format[0].bad_prefix + ', Wrong length: ' + s9format[0].wrong_length);
}
main().catch(console.error);
"

