    const prefix = s.substring(0, 6);
    let suffix = s.substring(6);
    suffix = suffix.replace(/[GI]/g, '6');
    suffix = suffix.replace(/[O]/g, '0');
    suffix = suffix.replace(/[S]/g, '5');
    suffix = suffix.replace(/[Z]/g, '2');
    suffix = suffix.replace(/[^0-9A-F]/g, '');
    s = prefix + suffix;
