import sys, json, os, glob

base = '/home/hein/.claude/projects/-home-hein-Workspace-FF-Next-js/'
files = sorted(glob.glob(base + '*.jsonl'), key=os.path.getmtime, reverse=True)[:15]

for f in files:
    fname = os.path.basename(f)
    size = os.path.getsize(f)
    print("=== {} (size: {}) ===".format(fname, size))
    count = 0
    with open(f) as fh:
        for line in fh:
            try:
                obj = json.loads(line)
                role = obj.get("type", obj.get("role", ""))
                if role == "human":
                    msg = obj.get("message", obj.get("content", ""))
                    if isinstance(msg, list):
                        parts = []
                        for m in msg:
                            if isinstance(m, dict):
                                parts.append(m.get("text", ""))
                        msg = " ".join(parts)
                    if isinstance(msg, str) and len(msg) > 10:
                        print(msg[:600])
                        print("---")
                        count += 1
            except:
                pass
    if count == 0:
        print("(no user messages found with type/role=human)")
    print()

