/**
 * usePermission Hook
 * Client-side permission checking for React components
 *
 * Usage:
 *   const { can, canAny, canAll, isLoading } = usePermission();
 *
 *   if (can('procurement.sourcing', 'edit')) { ... }
 *   if (canAny(['projects.list', 'activate.main'], 'view')) { ... }
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { log } from '@/lib/logger';

export type PermissionAction = 'view' | 'create' | 'edit' | 'delete';

export interface EffectivePermission {
  permissionKey: string;
  canView: boolean;
  canCreate: boolean;
  canEdit: boolean;
  canDelete: boolean;
}

interface UsePermissionReturn {
  /**
   * Check if user can perform action on permission
   */
  can: (permissionKey: string, action?: PermissionAction) => boolean;

  /**
   * Check if user can perform action on ANY of the permissions
   */
  canAny: (permissionKeys: string[], action?: PermissionAction) => boolean;

  /**
   * Check if user can perform action on ALL of the permissions
   */
  canAll: (permissionKeys: string[], action?: PermissionAction) => boolean;

  /**
   * Check if user can view a module (shorthand for can(key, 'view'))
   */
  canViewModule: (moduleKey: string) => boolean;

  /**
   * Check if user can access a page
   */
  canAccessPage: (pageKey: string) => boolean;

  /**
   * Get all effective permissions for current user
   */
  permissions: EffectivePermission[];

  /**
   * Loading state while fetching permissions
   */
  isLoading: boolean;

  /**
   * Refresh permissions from server
   */
  refresh: () => Promise<void>;
}

export function usePermission(): UsePermissionReturn {
  const { currentUser, isAuthenticated } = useAuth();
  const [permissions, setPermissions] = useState<EffectivePermission[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  // Track whether we've successfully fetched permissions at least once
  const [hasFetched, setHasFetched] = useState(false);

  // Check if user is super admin with 'all' permission
  // Checks both the mapped permissions array and the raw role string
  const isSuperAdmin = useMemo(() => {
    if (!currentUser) return false;
    return (
      currentUser.permissions?.includes('all' as never) ||
      currentUser.role === 'super_admin'
    );
  }, [currentUser]);

  // Fetch permissions from API
  const fetchPermissions = useCallback(async () => {
    if (!isAuthenticated || !currentUser?.id) {
      setPermissions([]);
      setIsLoading(false);
      return;
    }

    // Super admin has all permissions - no need to fetch
    if (isSuperAdmin) {
      setHasFetched(true);
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      const response = await fetch('/api/admin/permissions/me');

      if (response.ok) {
        const data = await response.json();
        setPermissions(data.data || []);
        setHasFetched(true);
      } else {
        log.error('Permissions API returned non-OK status', { status: response.status }, 'usePermission');
        setPermissions([]);
      }
    } catch (error) {
      log.error('Failed to fetch permissions', error, 'usePermission');
      setPermissions([]);
    } finally {
      setIsLoading(false);
    }
  }, [isAuthenticated, currentUser?.id, isSuperAdmin]);

  useEffect(() => {
    fetchPermissions();
  }, [fetchPermissions]);

  // Build permission lookup map
  const permissionMap = useMemo(() => {
    const map = new Map<string, EffectivePermission>();
    for (const perm of permissions) {
      map.set(perm.permissionKey, perm);
    }
    return map;
  }, [permissions]);

  // Check single permission
  const can = useCallback(
    (permissionKey: string, action: PermissionAction = 'view'): boolean => {
      // Super admin can do everything
      if (isSuperAdmin) return true;

      // While permissions haven't been fetched yet, allow view access
      // to prevent empty sidebar flash. Once loaded, enforce properly.
      if (!hasFetched && action === 'view') return true;

      const perm = permissionMap.get(permissionKey);
      if (!perm) return false;

      switch (action) {
        case 'view':
          return perm.canView;
        case 'create':
          return perm.canCreate;
        case 'edit':
          return perm.canEdit;
        case 'delete':
          return perm.canDelete;
        default:
          return false;
      }
    },
    [isSuperAdmin, permissionMap, hasFetched]
  );

  // Check any permission
  const canAny = useCallback(
    (permissionKeys: string[], action: PermissionAction = 'view'): boolean => {
      if (isSuperAdmin) return true;
      return permissionKeys.some(key => can(key, action));
    },
    [isSuperAdmin, can]
  );

  // Check all permissions
  const canAll = useCallback(
    (permissionKeys: string[], action: PermissionAction = 'view'): boolean => {
      if (isSuperAdmin) return true;
      return permissionKeys.every(key => can(key, action));
    },
    [isSuperAdmin, can]
  );

  // Shorthand for module view
  const canViewModule = useCallback(
    (moduleKey: string): boolean => can(moduleKey, 'view'),
    [can]
  );

  // Shorthand for page access
  const canAccessPage = useCallback(
    (pageKey: string): boolean => can(pageKey, 'view'),
    [can]
  );

  return {
    can,
    canAny,
    canAll,
    canViewModule,
    canAccessPage,
    permissions,
    isLoading,
    refresh: fetchPermissions,
  };
}

/**
 * Hook to check a single permission (simpler interface)
 *
 * Usage:
 *   const canEdit = useCanDo('procurement.sourcing', 'edit');
 */
export function useCanDo(
  permissionKey: string,
  action: PermissionAction = 'view'
): boolean {
  const { can } = usePermission();
  return can(permissionKey, action);
}

/**
 * Hook to get accessible modules for the current user
 */
export function useAccessibleModules(): string[] {
  const { permissions, isLoading } = usePermission();
  const { currentUser } = useAuth();

  return useMemo(() => {
    if (isLoading) return [];

    // Super admin can access all modules
    if (currentUser?.permissions?.includes('all') || currentUser?.role === 'super_admin') {
      return [
        'dashboard',
        'projects',
        'activate',
        'field',
        'noc',
        'people',
        'clients',
        'contractors',
        'procurement',
        'assets',
        'fleet',
        'communications',
        'analytics',
        'system',
      ];
    }

    // Filter to module-level permissions where user can view
    return permissions
      .filter(p => !p.permissionKey.includes('.') && p.canView)
      .map(p => p.permissionKey);
  }, [permissions, isLoading, currentUser]);
}

export default usePermission;

/**
 * useSystemFeatures Hook
 * Client-side hook for checking system feature settings
 *
 * Usage:
 *   const { isFeatureEnabled, isLoading } = useSystemFeatures();
 *
 *   if (isFeatureEnabled('system.data-sync.noc')) { ... }
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { log } from '@/lib/logger';

interface FeatureSetting {
  feature_key: string;
  enabled: boolean;
  config: Record<string, unknown>;
  updated_at: string;
}

interface UseSystemFeaturesReturn {
  /**
   * Check if a feature is enabled
   */
  isFeatureEnabled: (featureKey: string) => boolean;

  /**
   * Get all feature settings
   */
  features: FeatureSetting[];

  /**
   * Loading state while fetching features
   */
  isLoading: boolean;

  /**
   * Error message if fetch failed
   */
  error: string | null;

  /**
   * Refresh features from server
   */
  refresh: () => Promise<void>;
}

export function useSystemFeatures(): UseSystemFeaturesReturn {
  const [features, setFeatures] = useState<FeatureSetting[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchFeatures = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetch('/api/settings/system/features');

      if (response.ok) {
        const data = await response.json();
        if (data.success) {
          setFeatures(data.data || []);
        } else {
          throw new Error(data.error?.message || 'Failed to fetch features');
        }
      } else {
        throw new Error('Failed to fetch feature settings');
      }
    } catch (err) {
      log.error('useSystemFeatures', 'Failed to fetch features', err);
      setError(err instanceof Error ? err.message : 'Failed to fetch features');
      // On error, default to all features enabled
      setFeatures([]);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchFeatures();
  }, [fetchFeatures]);

  // Build feature lookup map
  const featureMap = useMemo(() => {
    const map = new Map<string, boolean>();
    for (const feature of features) {
      map.set(feature.feature_key, feature.enabled);
    }
    return map;
  }, [features]);

  // Check if feature is enabled
  const isFeatureEnabled = useCallback(
    (featureKey: string): boolean => {
      // If still loading or feature not found, default to enabled
      if (isLoading) return true;

      const enabled = featureMap.get(featureKey);
      // If not in the map, default to enabled
      return enabled !== undefined ? enabled : true;
    },
    [featureMap, isLoading]
  );

  return {
    isFeatureEnabled,
    features,
    isLoading,
    error,
    refresh: fetchFeatures,
  };
}

export default useSystemFeatures;

import { createContext, useContext, useEffect, useState, ReactNode, useCallback } from 'react';
import { AuthUser } from '@/services/authService';
import {
  User,
  UserRole,
  Permission,
  LoginCredentials,
  RegisterCredentials,
  PasswordResetRequest,
  ChangePasswordRequest,
  ROLE_PERMISSIONS,
} from '@/types/auth.types';
import { resetAuthErrorHandler } from '@/lib/authErrorHandler';

interface AuthContextType {
  // Legacy properties for backward compatibility
  user: AuthUser | null;
  loading: boolean;
  error: string | null;
  signInWithEmail: (email: string, password: string) => Promise<void>;
  signInWithGoogle: () => Promise<void>;
  signUp: (email: string, password: string, displayName?: string) => Promise<void>;
  signOut: () => Promise<void>;
  resetPassword: (email: string) => Promise<void>;

  // Enhanced properties with RBAC
  currentUser: User | null;
  isAuthenticated: boolean;
  signInWithEmailEnhanced: (credentials: LoginCredentials) => Promise<void>;
  signInWithGoogleEnhanced: (rememberMe?: boolean) => Promise<void>;
  registerWithEmail: (credentials: RegisterCredentials) => Promise<void>;
  resetPasswordEnhanced: (request: PasswordResetRequest) => Promise<void>;
  changePassword: (request: ChangePasswordRequest) => Promise<void>;
  sendEmailVerification: () => Promise<void>;
  updateProfile: (updates: Partial<User>) => Promise<void>;

  // Permission checking methods
  hasPermission: (permission: Permission) => boolean;
  hasAnyPermission: (permissions: Permission[]) => boolean;
  hasAllPermissions: (permissions: Permission[]) => boolean;
  hasRole: (role: UserRole) => boolean;
  hasAnyRole: (roles: UserRole[]) => boolean;

  // Utility methods
  clearError: () => void;
  refreshUser: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Map API role to UserRole enum
function mapRole(role: string): UserRole {
  const roleMap: Record<string, UserRole> = {
    'system': UserRole.SUPER_ADMIN,
    'super_admin': UserRole.SUPER_ADMIN,
    'admin': UserRole.ADMIN,
    'manager': UserRole.PROJECT_MANAGER,
    'technician': UserRole.FIELD_TECHNICIAN,
    'viewer': UserRole.VIEWER,
  };
  return roleMap[role] || UserRole.VIEWER;
}

// Map API user to internal User type
function mapApiUser(apiUser: {
  id: string;
  email: string;
  name?: string;
  firstName?: string;
  lastName?: string;
  role: string;
  permissions: string[];
  profilePicture?: string | null;
}): { user: User; authUser: AuthUser } {
  const role = mapRole(apiUser.role);
  const permissions = apiUser.permissions.includes('all')
    ? ['all' as Permission, ...Object.values(Permission)]
    : (apiUser.permissions as Permission[]);

  // Build display name from firstName/lastName or fall back to name or email
  const displayName = apiUser.firstName && apiUser.lastName
    ? `${apiUser.firstName} ${apiUser.lastName}`
    : apiUser.name || apiUser.email.split('@')[0];

  const user: User = {
    id: apiUser.id,
    email: apiUser.email,
    displayName,
    photoURL: apiUser.profilePicture || null,
    role,
    permissions,
    isEmailVerified: true,
    lastLoginAt: new Date(),
    createdAt: new Date(),
  };

  const authUser: AuthUser = {
    uid: apiUser.id,
    email: apiUser.email,
    displayName,

    displayName,
    photoURL: apiUser.profilePicture || null,
    emailVerified: true,
  };

  return { user, authUser };
}

